import type { Expense, Payroll } from '@/types';

/**
 * How a ledger row came to exist.
 *
 * `manual` rows are typed in by the Founder. `advance` and `payroll` rows are
 * generated by the posting functions in
 * `supabase/migrations/20261123000001_payroll_expense_posting.sql`, and their
 * money fields stay locked to the record that produced them.
 */
export type ExpenseSourceKind = 'manual' | 'payroll' | 'advance';

/**
 * Note written by `post_payroll_expense()`. Rows still carrying the untouched
 * note do not need to repeat it in the list; anything else was edited by hand.
 */
export const GENERATED_PAYROLL_NOTE_PREFIX = 'Generated from paid payroll vouchers';

export function expenseSourceOf(expense: Pick<Expense, 'source'>): ExpenseSourceKind {
  return expense.source === 'payroll' || expense.source === 'advance' ? expense.source : 'manual';
}

export function isLinkedExpense(expense: Pick<Expense, 'source'>): boolean {
  return expenseSourceOf(expense) !== 'manual';
}

export interface ExpenseTotals {
  count: number;
  total: number;
  labor: number;
  /** Labor rows that came from released advances. */
  advanceLabor: number;
  /** Labor rows that came from paid payroll runs. */
  payrollLabor: number;
  /** Labor typed in by hand (or older rows posted before this feature). */
  manualLabor: number;
}

const round2 = (value: number) => Math.round(value * 100) / 100;

export function summarizeExpenses(list: Expense[]): ExpenseTotals {
  const totals: ExpenseTotals = {
    count: list.length,
    total: 0,
    labor: 0,
    advanceLabor: 0,
    payrollLabor: 0,
    manualLabor: 0,
  };

  for (const expense of list) {
    const amount = Number(expense.amount || 0);
    totals.total += amount;
    if (expense.category === 'labor') {
      totals.labor += amount;
      const source = expenseSourceOf(expense);
      if (source === 'advance') totals.advanceLabor += amount;
      else if (source === 'payroll') totals.payrollLabor += amount;
      else totals.manualLabor += amount;
    }
  }

  totals.total = round2(totals.total);
  totals.labor = round2(totals.labor);
  totals.advanceLabor = round2(totals.advanceLabor);
  totals.payrollLabor = round2(totals.payrollLabor);
  totals.manualLabor = round2(totals.manualLabor);
  return totals;
}

/** `2026-11-17 → 2026-11-23` (single day collapses to one date). */
export function formatPeriodLabel(start?: string | null, end?: string | null): string | null {
  if (!start || !end) return null;
  return start === end ? start : `${start} → ${end}`;
}

/**
 * Deep link back to the payroll page for the run this row came from, with the
 * period and site already applied. `print` opens the 3×3 slip dialog there so
 * the print document keeps living in one place.
 */
export function payrollExpenseHref(expense: Expense, options: { print?: boolean } = {}): string | null {
  if (expenseSourceOf(expense) !== 'payroll') return null;
  const start = expense.payroll_period_start;
  const end = expense.payroll_period_end;
  if (!start || !end) return null;
  const params = new URLSearchParams({ period_start: start, period_end: end, site: expense.project_id });
  if (options.print) params.set('print', '1');
  return `/payroll?${params.toString()}`;
}

export function advanceExpenseHref(): string {
  return '/advances?tab=issued';
}

export interface PayrollRunRow {
  id: string;
  workerName: string;
  days: number | null;
  gross: number;
  bale: number;
  net: number;
}

export interface PayrollRunBreakdown {
  rows: PayrollRunRow[];
  paidVouchers: number;
  totalVouchers: number;
  gross: number;
  bale: number;
  net: number;
}

/**
 * The vouchers behind a payroll expense: paid vouchers of that site and period,
 * which is exactly what `post_payroll_expense()` summed. Gross is per worker;
 * the Bale column is what payroll recovered from an advance that was already
 * expensed, so only the net column is new money.
 */
export function payrollRunBreakdown(
  payroll: Payroll[],
  workers: { id: string; name: string }[],
  expense: Pick<Expense, 'source' | 'project_id' | 'payroll_period_start' | 'payroll_period_end'>
): PayrollRunBreakdown {
  const empty: PayrollRunBreakdown = {
    rows: [],
    paidVouchers: 0,
    totalVouchers: 0,
    gross: 0,
    bale: 0,
    net: 0,
  };
  if (expenseSourceOf(expense) !== 'payroll') return empty;
  if (!expense.payroll_period_start || !expense.payroll_period_end) return empty;

  const inRun = payroll.filter(
    (pay) =>
      pay.project_id === expense.project_id &&
      pay.period_start === expense.payroll_period_start &&
      pay.period_end === expense.payroll_period_end
  );
  const paid = inRun.filter((pay) => pay.status === 'paid');

  const rows = paid
    .map((pay) => ({
      id: pay.id,
      workerName: workers.find((worker) => worker.id === pay.worker_id)?.name || 'Worker',
      days: pay.days_worked ?? null,
      gross: round2(Number(pay.gross_pay || 0)),
      bale: round2(Number(pay.bale_deduction || 0)),
      net: round2(Number(pay.net_pay || 0)),
    }))
    .sort((a, b) => a.workerName.localeCompare(b.workerName));

  return {
    rows,
    paidVouchers: paid.length,
    totalVouchers: inRun.length,
    gross: round2(rows.reduce((sum, row) => sum + row.gross, 0)),
    bale: round2(rows.reduce((sum, row) => sum + row.bale, 0)),
    net: round2(rows.reduce((sum, row) => sum + row.net, 0)),
  };
}
